#include "calc.h"
#include <stdio.h>
#include <stdlib.h>

/**
 * @brief Función para mostrar el menú de opciones al usuario.
 * 
 * Esta función muestra un menú con las operaciones disponibles y solicita al usuario que elija una opción.
 * Sólo está disponible en el modo interactivo, no en el modo terminal.
 * @return int Devuelve la opción elegida por el usuario (un entero entre 1 y 11).
 */
int mostrar_menu(){

	int opcion = 0;

	printf("\n==== CALCULADORA DISTRIBUIDA ===========\n");
	printf("Operaciones del MODO BÁSICO: \n");
	printf("1. Sumar                            '+'\n");
	printf("2. Restar                           '-'\n");
	printf("3. Multiplicar                      'x'\n");
	printf("4. Dividir                          '/'\n");
	printf("Operaciones del MODO AVANZADO: \n");
	printf("5. Potencia                         '^'\n");
	printf("6. Logaritmo en base 10             'L'\n");
	printf("7. Logaritmo neperiano (base e)     'l'\n");
	printf("8. Seno (valor input en grados)     's'\n");
	printf("9. Coseno (valor input en grados)   'c'\n");
	printf("10. Tangente (valor input en grados)'t'\n");
	printf("11. Calcular un lote de operaciones.\n");
	printf("==========================================\n");
	do{
		printf("\nElige una opción (1-11): ");
		scanf("%d", &opcion);
	} while (opcion < 1 || opcion > 11 );	

	return opcion;
}

/**
 * @brief Función para procesar la opción elegida por el usuario en el menú y devolver el operador correspondiente.
 * 
 * @param opcion La opción elegida por el usuario (un entero entre 1 y 11).
 * @return char El operador correspondiente a la opción elegida por el usuario.
 * Si la opción no es válida, se muestra un mensaje de error y se termina el programa.
 */
char procesar_menu(int opcion){ /* Devuelve el operador deseado*/
	char operando;

	switch (opcion){
		case OP_SUMA: /* 1 */
			operando = '+';
			break;

		case OP_RESTA: /* 2 */
			operando = '-';
			break;

		case OP_MULTIPLICACION: /* 3 */
			operando = 'x';
			break;

		case OP_DIVISION: /* 4 */
			operando = '/';
			break;

		case OP_POTENCIA: /* 5 */
			operando = '^';
			break;

		case OP_LOG10: /* 6 */
			operando = 'L';
			break;

		case OP_LOGN: /* 7 */
			operando = 'l';
			break;

		case OP_SENO: /* 8 */
			operando = 's';
			break;

		case OP_COSENO: /* 9 */
			operando = 'c';
			break;

		case OP_TANGENTE: /* 10 */
			operando = 't';
			break;
	
		default:
			printf("Error. La opción %d no es válida", opcion);
			exit(1);
	}

	return operando;
}

/**
 * @brief Función para leer un lote de operaciones desde la entrada estándar.
 * 
 * @param lote Un puntero a una estructura de tipo operaciones donde se almacenarán las operaciones leídas.
 * @param array_aux Un array auxiliar de tipo operacion donde se almacenarán temporalmente las operaciones leídas 
 *   		   antes de asignarlas a la estructura lote.
 * @return void
 */
void leer_lote(operaciones *lote, operacion *array_aux){

	int num_oper;
	operacion oper;

	printf("\nIndique cuántas operaciones desea realizar por lote (máx %d): ", MAX_OP);
	scanf("%d", &num_oper);

	/* Comprobamos que ha introducido un nro de veces correcto */
	if(num_oper > MAX_OP) num_oper = MAX_OP;
	if(num_oper < 1) num_oper = 1;

	
	for(int i = 0; i < num_oper; i++){

		printf("\n----- Introduzca la operación nro %d -------", i+1);

		/* Leemos los operandos y el operador. */
		printf("\nIntroduzca el 1er operando: ");
		scanf("%lf", &oper.op1);

		printf("Introduzca el operador (+ - x / ^ L l s c t): ");
		scanf(" %c", &oper.operador); /* Importante dejar un espacio para que nos e trague el '\n' de la entrada anterior*/
		
		/* Sólo leemos el segundo operando si la operación lo necesita. Si no lo necesita, no se lee. */
		if(oper.operador == '+' || oper.operador == '-' || oper.operador == 'x' || 
			oper.operador == '/' || oper.operador == '^'){
			printf("Introduzca el 2o operando: ");
			scanf("%lf", &oper.op2);
		} else {
			oper.op2 = 0.0;
		}

		/* Lo guardamos en el array auxiliar */
		array_aux[i] = oper;

		printf("------ Operación nro %d leida.--------------\n", i+1);
	}

	printf("\n-----> El lote se ha leído correctamente <------\n");


	/* Asignamos la memoria y el tamaño al lote,*/
	lote->operaciones_val = array_aux;
	lote->operaciones_len = num_oper;
}

/**
 * @brief Función para realizar una operación simple solicitada por el usuario.
 * Se utiliza en el modo menú y en el modo terminal (pasando los parametros como argumentos del programa)
 * 
 * @param host El nombre del host donde se encuentra el servidor de la calculadora.
 * @param op1 El primer operando de la operación.
 * @param op2 El segundo operando de la operación (si la operación lo necesita,
 * 		  si no lo necesita, se puede pasar cualquier valor, ya que no se utilizará).
 * @param operador El operador de la operación (por ejemplo, '+', '-', 'x', '/', '^', 'L', 'l', 's', 'c' o 't').
 * @return void
 */
void calcprog_1(char *host, double op1, double op2, char operador){

	CLIENT *clnt;
	double *result; /* Lo utilizaremos para el resultado de las operacion solicitada*/

	#ifndef	DEBUG
		clnt = clnt_create (host, CALCPROG, CALCVER, "udp");
		if (clnt == NULL) {
			clnt_pcreateerror (host);
			exit (1);
		}
	#endif	/* DEBUG */

	/* Hacemos un switch-case para identificar la operación que ha pedido el usuario*/

	switch (operador){
		case '+':
			result = suma_1(op1, op2, clnt);
			break;

		case '-':
			result = resta_1(op1, op2, clnt);
			break;
		
		case 'x': /* Se utiiza x en lugar de * porque si no, al leer desde la terminal puede dar fallo*/
			result = multiplicacion_1(op1, op2, clnt);
			break;
		
		case '/':
			result = division_1(op1, op2, clnt);
			break;
		
		case '^':
			result = potencia_1(op1, op2, clnt);
			break;
		
		case 'L':
			result = log10_1(op1, clnt);
			break;
		
		case 'l':
			result = logn_1(op1, clnt);
			break;

		case 's':
			result = seno_1(op1, clnt);
			break;

		case 'c':
			result = coseno_1(op1, clnt);
			break;

		case 't':
			result = tangente_1(op1, clnt);
			break;

		default:
			printf("Error: El operador %c no es válido.\n", operador);
			exit(1);
	}

	/* Comprobamos que se ha realizado las oepracion correctamente*/
	if (result == (double *) NULL) {
        clnt_perror (clnt, "Error en la llamada al servidor");
    } else {
        printf("\nEl resultado de la operación es: %.3f\n", *result);
    }

	#ifndef	DEBUG
		clnt_destroy (clnt);
	#endif	 /* DEBUG */
}

/**
 * @brief Función para calcular un lote de operaciones solicitadas por el usuario.
 * @param host El nombre del host donde se encuentra el servidor de la calculadora.
 * @param lote El lote de operaciones a calcular.
 * @return void
 */
void calcproglotes(char *host, operaciones lote){

	CLIENT *clnt;
	resultados *result; /* Puntero a un array de tipo resultados para ir almacenando los resultados */

	#ifndef DEBUG
		clnt = clnt_create(host, CALCPROG, CALCVER, "udp");
		if (clnt == NULL)
		{
			clnt_pcreateerror(host);
			exit(1);
		}
	#endif /* DEBUG */

	/* Llamamos a la función correspondiente apra que nos calcule el lote */
	result = calcular_lotes_1(lote, clnt);

	/* Comprobamos que se ha realizado las operaciones correctamente*/
	if (result == (resultados *) NULL) {
        clnt_perror (clnt, "Error en la llamada al servidor");
    } else {
        printf("\n=== RESULTADOS DEL CÁLCULO DEL LOTE ======\n");
		
		for(int i = 0; i < result->resultados_len; i++){
			/* lote y el array  de resultados (al que apunta result) tienen los mismos tamaños */
			double op1 = lote.operaciones_val[i].op1;
			char operador = lote.operaciones_val[i].operador;
			double op2 = lote.operaciones_val[i].op2;
			double resultado = result->resultados_val[i];

			switch (operador){
				
				/* Suma, Resta, Multiplicación, División y Potencia se muestran de la misma forma*/
				case '+':
				case '-':
				case 'x':
				case '/':
				case '^':
					printf("%.3f %c %.3f = %.3f\n", op1, operador, op2, resultado);
					break;
				
				case 'L': 
					printf("log10(%.3f) = %.3f\n", op1, resultado);
					break;
				
				case 'l':
					printf("ln(%.3f) = %.3f\n", op1, resultado);
					break;

				case 's':
					printf("sen(%.3f) = %.3f\n", op1, resultado);
					break;

				case 'c':
					printf("cos(%.3f) = %.3f\n", op1, resultado);
					break;

				case 't':
					printf("tan(%.3f) = %.3f\n", op1, resultado);
					break;
			
			default:
				break;
			}
			
		}

		printf("===========================================\n");
    }

	#ifndef DEBUG
		clnt_destroy(clnt);
	#endif /* DEBUG */
}



int main (int argc, char *argv[]) {
	char *host;
	double op1, op2; /* Operandos para las operaciones */
	char operador;

	if (argc == 5){ /* El usuario ha pasado los operandos por la terminal. */

		/* Extraemos los parámetros */
		host = argv[1]; /* Sería host = máquina */
		op1 = atof(argv[2]);
		operador = argv[3][0]; /*Se añade el [0] para que sólo se quede con el primer carácter (ya que argv[3] es un char *)*/
		op2 = atof(argv[4]);

		/* Realizamos la operación simple */
		calcprog_1(host, op1, op2, operador);

	} else if (argc == 2){ /* El usuario quiere que se le muestre el menú de opciones.*/ 

		host = argv[1];

		int opcion = mostrar_menu();

		if (opcion == CALCULAR_LOTES){
			operaciones lote;
			operacion array_aux[MAX_OP]; /* Array estático y auxiliar para almacenar las operaciones leidas. */
			leer_lote(&lote, array_aux);
			calcproglotes(host, lote);

		} else { /* El usuario desea realizar alguna operación simple. */
			operador = procesar_menu(opcion);

			printf("\nIntroduzca el 1er operando: ");
			scanf("%lf", &op1);

			if(opcion == OP_SUMA || opcion == OP_RESTA || opcion == OP_MULTIPLICACION ||
				opcion == OP_DIVISION || opcion == OP_POTENCIA){
				printf("Introduzca el 2o operando: ");
				scanf("%lf", &op2);	
			}else{
				op2 = 0.0;
			}

			/* Realizamos la operación simple */
			calcprog_1(host, op1, op2, operador);
		}

	} else { /* El número de parámetros es incorrecto*/
		printf("Error al pasar los parámetros.\n");
		printf("Uso por terminal: %s <maquina> <numero> <operador> <numero>\n", argv[0]);
		printf("Uso por menú:     %s <maquina>\n", argv[0]);
		exit(1);
		}
}
